const items = $input.all();
const first = items[0] || { json: {} };
const headers = (first.json && first.json.headers) || {};
const got = String(headers['x-bp-signature'] || headers['X-BP-Signature'] || '');

function readSecret() {
  try { if (typeof $vars !== 'undefined' && $vars && $vars.WA_BRIDGE_SECRET) return String($vars.WA_BRIDGE_SECRET); } catch (e) {}
  try { if (typeof $env !== 'undefined' && $env && $env.WA_BRIDGE_SECRET) return String($env.WA_BRIDGE_SECRET); } catch (e) {}
  return '';
}
const secret = readSecret();
if (!secret) return [{ json: { ok: false, reason: 'no-secret-configured' } }];

let raw = '';
try {
  if (first.binary && first.binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    raw = buf.toString('utf8');
  }
} catch (e) { raw = ''; }
if (!raw && first.json && typeof first.json.rawBody === 'string') raw = first.json.rawBody;
if (!raw && first.json && first.json.body) raw = JSON.stringify(first.json.body);
if (!raw) return [{ json: { ok: false, reason: 'empty-body' } }];

async function hmacHex(message, key) {
  try {
    const enc = new TextEncoder();
    const ck = await crypto.subtle.importKey('raw', enc.encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const sig = await crypto.subtle.sign('HMAC', ck, enc.encode(message));
    const bytes = new Uint8Array(sig);
    let hex = '';
    for (let i = 0; i < bytes.length; i += 1) hex += bytes[i].toString(16).padStart(2, '0');
    return hex;
  } catch (e) {
    const nodeCrypto = require('crypto');
    return nodeCrypto.createHmac('sha256', key).update(message, 'utf8').digest('hex');
  }
}
const expected = 'sha256=' + (await hmacHex(raw, secret));
let same = got.length === expected.length;
if (same) { let diff = 0; for (let i = 0; i < expected.length; i += 1) { if (got.charCodeAt(i) !== expected.charCodeAt(i)) diff += 1; } same = diff === 0; }
if (!same) return [{ json: { ok: false, reason: 'bad-signature' } }];

let payload = null;
try { payload = JSON.parse(raw); } catch (e) { return [{ json: { ok: false, reason: 'bad-json' } }]; }
if (!payload || payload.v !== 1) return [{ json: { ok: false, reason: 'bad-version' } }];
if (payload.account !== 'company' && payload.account !== 'personal') return [{ json: { ok: false, reason: 'unknown-account' } }];
if (!Array.isArray(payload.messages) || !payload.messages.length) return [{ json: { ok: false, reason: 'no-messages' } }];
return [{ json: { ok: true, payload: payload } }];

const sd = $getWorkflowStaticData('global');
sd.seenMsg = sd.seenMsg || {};
const now = Date.now();
const WINDOW = 48 * 60 * 60 * 1000;
const keys = Object.keys(sd.seenMsg);
for (let i = 0; i < keys.length; i += 1) { if (now - sd.seenMsg[keys[i]] > WINDOW) delete sd.seenMsg[keys[i]]; }
if (Object.keys(sd.seenMsg).length > 6000) sd.seenMsg = {};

const p = ($json && $json.payload) || {};
const account = String(p.account || '');
const chatId = String(p.chat_id || '');
const isGroup = p.is_group === true;
const fresh = [];
for (const m of p.messages || []) {
  const id = String(m.message_id || '');
  if (!id) continue;
  const key = chatId + '|' + id;
  if (sd.seenMsg[key]) continue;
  sd.seenMsg[key] = now;
  fresh.push(m);
}
if (!fresh.length) return [];

const fmt = function (ts) { return new Date((Number(ts) || 0) * 1000).toLocaleString('ar-SA', { timeZone: 'Asia/Riyadh', day: 'numeric', month: 'numeric', hour: '2-digit', minute: '2-digit' }); };
const lines = [];
let counterName = '';
let counterMsisdn = '';
for (const m of fresh) {
  const who = m.from_me ? 'باهر' : (m.sender_name || m.sender_msisdn || 'الطرف الآخر');
  if (!m.from_me && !counterMsisdn) { counterMsisdn = String(m.sender_msisdn || ''); counterName = String(m.sender_name || ''); }
  let body = String(m.text || '');
  if (m.kind !== 'text') body = '[' + m.kind + (m.media_name ? ' · ' + m.media_name : '') + ']' + (body ? ' ' + body : '');
  if (m.quoted_text) body = '(رداً على: ' + String(m.quoted_text).slice(0, 160) + ') ' + body;
  lines.push('[' + fmt(m.ts) + '] ' + who + ': ' + body.slice(0, 900));
}
if (!counterMsisdn && !isGroup) counterMsisdn = chatId.split('@')[0].replace(/\D/g, '');
if (!counterName) counterName = String(p.chat_name || '');
const transcript = lines.slice(0, 40).join('\n').slice(0, 7000);

const prompt = 'أنت قارئ محادثات واتساب لباهر مجنس في Business Partner. تقرأ ولا ترسل شيئاً.\n' +
  'مهمتك: تلخيص دفعة الرسائل أدناه وتصنيفها، وإعادة JSON صِرف بلا أي نص قبله أو بعده وبلا علامات ```.\n' +
  'الحقول المطلوبة بالحرف:\n' +
  '{"summary_ar":"","intent":"real_estate_demand|real_estate_supply|client_request|offer_received|task|personal|noise",' +
  '"urgency":"high|medium|low","client_name":"","client_msisdn":"","city":"","property_category":"",' +
  '"budget":null,"size_sqm":null,"service":"","task_title":"","task_due":"","suggested_reply_ar":"","needs_baher":true}\n\n' +
  'القواعد:\n' +
  '- العربية سعودية بسيطة ومباشرة. summary_ar في ثلاثة أسطر على الأكثر.\n' +
  '- intent = noise لكل ما ليس عملاً: سلامات، شكر، صور عائلية، دعابات، رسائل مجموعات بلا طلب.\n' +
  '- intent = personal للشخصي الذي يهم باهر لكنه ليس عملاً.\n' +
  '- real_estate_demand: أحدهم يطلب عقاراً. real_estate_supply: أحدهم يعرض عقاراً.\n' +
  '- offer_received: عرض سعر أو عرض خدمة وصل من مورّد أو شريك.\n' +
  '- client_request: طلب خدمة من عميل. task: شيء على باهر أن يفعله.\n' +
  '- city من هذه القائمة فقط: Riyadh, Jeddah, Dammam, Khobar, Makkah, Madinah, Other. وإن لم تُذكر مدينة فاتركها فارغة.\n' +
  '- property_category من هذه القائمة فقط: Residential, Commercial, Office, Co-working Space, Retail, Showroom, Industrial, Land, Labor Camp, Compound, Mixed-use, Hospitality, Workshop, Factory, Building, Other. وإن لم تُذكر فاتركها فارغة.\n' +
  '- budget و size_sqm أرقام بلا فواصل، أو null إن لم تُذكر. لا تخترع رقماً.\n' +
  '- ممنوع تماماً اختراع سعر خدمة أو معلومة حكومية أو رسم رسمي. ما لم يُذكر في الرسائل لا يُكتب.\n' +
  '- suggested_reply_ar اقتراحٌ لباهر ليقرأه وينسخه بنفسه — لا يُرسل آلياً. بلا سعر وبلا وعد وبلا ضمان.\n' +
  '- needs_baher = true فقط إذا كان على باهر فعلٌ أو ردّ.\n' +
  '- task_due بصيغة ISO (YYYY-MM-DD) إن ذُكر موعد، وإلا فارغ.\n\n' +
  'سياق المحادثة:\n' +
  'الحساب: ' + (account === 'company' ? 'رقم الشركة 966530540231' : 'الرقم الشخصي 966503793356') + '\n' +
  'المحادثة: ' + String(p.chat_name || chatId) + (isGroup ? ' (مجموعة)' : ' (فردية)') + '\n' +
  'الطرف الآخر: ' + (counterName || '—') + ' · ' + (counterMsisdn || '—') + '\n\n' +
  'الرسائل:\n' + transcript;

return [{ json: {
  prompt: prompt,
  account: account,
  account_msisdn: String(p.account_msisdn || ''),
  chat_id: chatId,
  chat_name: String(p.chat_name || ''),
  is_group: isGroup,
  counterpart_name: counterName,
  counterpart_msisdn: counterMsisdn,
  message_count: fresh.length,
  transcript: transcript
} }];

const CITIES = ['Riyadh','Jeddah','Dammam','Khobar','Makkah','Madinah','Other'];
const CATS = ['Residential','Commercial','Office','Co-working Space','Retail','Showroom','Industrial','Land','Labor Camp','Compound','Mixed-use','Hospitality','Workshop','Factory','Building','Other'];
const INTENTS = ['real_estate_demand','real_estate_supply','client_request','offer_received','task','personal','noise'];

const meta = $('Dedupe & Fold Batch').first().json;
let text = String(($json && ($json.text || $json.output || $json.response)) || '');
text = text.replace(/^[\s\S]*?```(?:json)?/i, '').replace(/```[\s\S]*$/, '').trim();
if (!text) text = String(($json && ($json.text || $json.output)) || '').trim();
const open = text.indexOf('{');
const close = text.lastIndexOf('}');
if (open >= 0 && close > open) text = text.slice(open, close + 1);

let m = null;
try { m = JSON.parse(text); } catch (e) { m = null; }
if (!m || typeof m !== 'object') {
  m = { summary_ar: 'تعذّر قراءة مخرج النموذج — راجع المحادثة بنفسك.', intent: 'task', urgency: 'medium', needs_baher: true, task_title: 'راجع محادثة واتساب: ' + String(meta.chat_name || meta.chat_id) };
}

const pick = function (value, list) { const v = String(value || '').trim(); return list.indexOf(v) >= 0 ? v : ''; };
const num = function (value) { const n = Number(value); return Number.isFinite(n) && n > 0 ? n : null; };

let intent = pick(m.intent, INTENTS) || 'noise';
let urgency = pick(m.urgency, ['high','medium','low']) || 'medium';
let needsBaher = m.needs_baher === true;
let taskTitle = String(m.task_title || '').trim().slice(0, 180);

if (meta.is_group === true && (intent === 'client_request' || intent === 'offer_received')) {
  const clearAsk = taskTitle.length > 0;
  if (!clearAsk) { intent = 'task'; taskTitle = 'متابعة من مجموعة: ' + String(meta.chat_name || meta.chat_id).slice(0, 120); }
}
if (intent === 'noise' || intent === 'personal') { needsBaher = false; taskTitle = ''; urgency = 'low'; }
if (intent === 'task' && !taskTitle) taskTitle = 'متابعة محادثة: ' + String(meta.chat_name || meta.chat_id).slice(0, 120);

let due = String(m.task_due || '').trim();
if (due && Number.isNaN(new Date(due).getTime())) due = '';
if (!due) due = new Date(Date.now() + 36 * 60 * 60 * 1000).toISOString();
else due = new Date(due).toISOString();

const priority = urgency === 'high' ? 'High' : (urgency === 'low' ? 'Low' : 'Medium');
const recordType = intent === 'real_estate_supply' ? 'Supply - For Rent' : 'Demand - Client Request';
const leadType = intent === 'offer_received' ? 'مورّد' : 'عميل محتمل';
const name = String(m.client_name || meta.counterpart_name || '').trim().slice(0, 120);
const msisdn = String(m.client_msisdn || meta.counterpart_msisdn || '').replace(/\D/g, '');
const summary = String(m.summary_ar || '').trim().slice(0, 1800);
const reply = String(m.suggested_reply_ar || '').trim().slice(0, 900);

const sd = $getWorkflowStaticData('global');
sd.daily = sd.daily || {};
const dayKey = new Date(Date.now() + 3 * 60 * 60 * 1000).toISOString().slice(0, 10);
const day = sd.daily[dayKey] || { batches: 0, chats: {}, real_estate: 0, client_requests: 0, offers: 0, tasks: 0, noise: 0 };
day.batches += 1;
day.chats[String(meta.chat_id || '')] = 1;
if (intent === 'real_estate_demand' || intent === 'real_estate_supply') day.real_estate += 1;
else if (intent === 'client_request') day.client_requests += 1;
else if (intent === 'offer_received') day.offers += 1;
else if (intent === 'task') day.tasks += 1;
else day.noise += 1;
sd.daily[dayKey] = day;
const dayKeys = Object.keys(sd.daily);
for (let i = 0; i < dayKeys.length; i += 1) { if (dayKeys[i] < dayKey && (new Date(dayKey) - new Date(dayKeys[i])) > 10 * 86400000) delete sd.daily[dayKeys[i]]; }

return [{ json: {
  intent: intent,
  urgency: urgency,
  priority: priority,
  needs_baher: needsBaher,
  record_type: recordType,
  lead_type: leadType,
  summary_ar: summary,
  suggested_reply_ar: reply,
  client_name: name || 'غير معروف',
  client_msisdn: msisdn,
  city: pick(m.city, CITIES),
  property_category: pick(m.property_category, CATS),
  budget: num(m.budget),
  size_sqm: num(m.size_sqm),
  service: String(m.service || '').slice(0, 180),
  task_title: taskTitle,
  task_due: due,
  task_id: 'wa-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 7),
  account: meta.account,
  chat_id: meta.chat_id,
  chat_name: meta.chat_name,
  is_group: meta.is_group,
  message_count: meta.message_count,
  record_source: 'WhatsApp Web — ' + String(meta.account || ''),
  engine_fallback: null
} }];

const sd = $getWorkflowStaticData('global');
sd.alerted = sd.alerted || {};
const now = Date.now();
const COOLDOWN = 24 * 60 * 60 * 1000;
const keys = Object.keys(sd.alerted);
for (let i = 0; i < keys.length; i += 1) { if (now - sd.alerted[keys[i]] > COOLDOWN) delete sd.alerted[keys[i]]; }

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.needs_baher !== true) continue;
  if (j.urgency === 'low') continue;
  const chat = String(j.chat_id || '');
  if (!chat) continue;
  if (sd.alerted[chat] && now - sd.alerted[chat] < COOLDOWN) continue;
  sd.alerted[chat] = now;
  const who = String(j.client_name || 'غير معروف') + ' — ' + (j.client_msisdn ? '+' + j.client_msisdn : 'بلا رقم');
  const link = j.notion_url ? String(j.notion_url) : 'لم يُسجّل — راجع نوشن';
  const reply = String(j.suggested_reply_ar || '').trim();
  const text = 'باهر، ترى في واحد وصل معك:\n' + who + '\n' + String(j.summary_ar || '') +
    (reply ? '\nالمقترح أن تردّ: «' + reply + '»' : '') +
    '\nالطلب سُجّل في نوشن: ' + link;
  out.push({ json: { text: text, chat_id: chat } });
}
return out;

const sd = $getWorkflowStaticData('global');
sd.daily = sd.daily || {};
const riyadhNow = new Date(Date.now() + 3 * 60 * 60 * 1000);
const y = new Date(riyadhNow.getTime() - 86400000).toISOString().slice(0, 10);
const d = sd.daily[y];
const label = new Date(y + 'T00:00:00Z').toLocaleDateString('ar-SA', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long' });
if (!d) {
  return [{ json: {
    text: 'تقرير قارئ واتساب — ' + label + '\nما وصلني شيء أمس. إما ما جاءت رسائل عمل، أو الجسر كان متوقّفاً.',
    subject: 'قارئ واتساب — تقرير ' + y + ' (لا بيانات)'
  } }];
}
const chats = Object.keys(d.chats || {}).length;
const text = 'تقرير قارئ واتساب — ' + label + '\n' +
  'محادثات: ' + chats + ' · دفعات: ' + (d.batches || 0) + '\n' +
  'طلبات عملاء جديدة: ' + (d.client_requests || 0) + '\n' +
  'عروض وصلت: ' + (d.offers || 0) + '\n' +
  'عقارات (طلب/عرض): ' + (d.real_estate || 0) + '\n' +
  'مهام فُتحت لك: ' + (d.tasks || 0) + '\n' +
  'أُسقط كضجيج: ' + (d.noise || 0) + '\n\n' +
  'التفاصيل في نوشن: العقارات، وSales Pipeline، وTasks.';
return [{ json: { text: text, subject: 'قارئ واتساب — تقرير ' + y } }];
